package com.gestordevendas.api.food; import com.gestordevendas.api.company.Company; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="snack_orders") public class SnackOrder { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="courier_id") private Courier courier; @Column(name="client_name",nullable=false) private String clientName; @Column(name="client_phone") private String clientPhone; @Column(name="client_city") private String clientCity; @Column(name="items_text",nullable=false,columnDefinition="TEXT") private String itemsText; @Column(name="items_total",nullable=false) private BigDecimal itemsTotal; @Column(name="delivery_fee",nullable=false) private BigDecimal deliveryFee; @Column(name="total",nullable=false) private BigDecimal total; @Column(name="cost_total",nullable=false) private BigDecimal costTotal=BigDecimal.ZERO; @Column(name="kitchen_status",nullable=false) private String kitchenStatus="PENDING"; @Enumerated(EnumType.STRING) @Column(name="payment_method",nullable=false) private PaymentMethod paymentMethod=PaymentMethod.PIX; @Column(name="cash_received") private BigDecimal cashReceived; @Column(name="change_amount",nullable=false) private BigDecimal changeAmount=BigDecimal.ZERO; @Column(name="created_at",nullable=false) private Instant createdAt; protected SnackOrder(){} public static SnackOrder create(Company c,Courier courier,String cn,String cp,String city,String txt,BigDecimal items,BigDecimal fee,BigDecimal cost,PaymentMethod method,BigDecimal cash){var x=new SnackOrder();x.id=UUID.randomUUID();x.company=c;x.courier=courier;x.clientName=cn;x.clientPhone=cp;x.clientCity=city;x.itemsText=txt;x.itemsTotal=items;x.deliveryFee=fee;x.total=items.add(fee);x.costTotal=cost==null?BigDecimal.ZERO:cost;x.paymentMethod=method==null?PaymentMethod.PIX:method;x.cashReceived=x.paymentMethod==PaymentMethod.CASH?cash:null;x.changeAmount=x.paymentMethod==PaymentMethod.CASH&&cash!=null?cash.subtract(x.total).max(BigDecimal.ZERO):BigDecimal.ZERO;x.createdAt=Instant.now();return x;} public UUID getId(){return id;} public Courier getCourier(){return courier;} public String getClientName(){return clientName;} public String getClientPhone(){return clientPhone;} public String getClientCity(){return clientCity;} public String getItemsText(){return itemsText;} public BigDecimal getItemsTotal(){return itemsTotal;} public BigDecimal getDeliveryFee(){return deliveryFee;} public BigDecimal getTotal(){return total;} public BigDecimal getCostTotal(){return costTotal;} public String getKitchenStatus(){return kitchenStatus;} public PaymentMethod getPaymentMethod(){return paymentMethod;} public BigDecimal getCashReceived(){return cashReceived;} public BigDecimal getChangeAmount(){return changeAmount;} public Instant getCreatedAt(){return createdAt;} public void setKitchenStatus(String status){this.kitchenStatus=status;} }
